    mid = n // 2
    if n % 2 == 0:
        return (nums_sorted[mid - 1] + nums_sorted[mid]) / 2
    else:
        return float(nums_sorted[mid])

def dedupe(xs: list) -> list:
    seen = set()
    result = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            result.append(x)
    return result

def fizzbuzz(n: int) -> list:
    result = []
    for i in range(1, n + 1):
        s = ""
        if i % 3 == 0:
            s += "Fizz"
        if i % 5 == 0:
            s += "Buzz"
        result.append(s or str(i))
    return result

def valid_parens(s: str) -> bool:
    stack = []
    mapping = {
        ')': '(',
        ']': '[',
        '}': '{'
    }
    for char in s:
        if char in mapping:
            if not stack or stack.pop() != mapping[char]:
                return False
        else:
            if char in '([{':
                stack.append(char)
    return not stack

import pandas as pd

def fx_rate(date: str) -> float:
    df = pd.read_csv('data/ecb_rates_2019.csv')
    row = df[df['Date'] == date]
    if row.empty:
        return 0.0
    return float(row['Rate'].str.replace(',', '').str.replace('$', '').iloc[0])

def parse_price(s: str) -> float:
    s = s.replace('$', '').replace(',', '')
    return float(s)
